code.python:
class Solution:
    def mountainTop(self, elevations: List[int]) -> int:
        lo, hi = 0, len(elevations) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if elevations[mid] < elevations[mid + 1]:
                lo = mid + 1
            else:
                hi = mid
        return lo

code.java:
class Solution {
    public int mountainTop(int[] elevations) {
        int lo = 0, hi = elevations.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (elevations[mid] < elevations[mid + 1]) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

